<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Employee Management</title><style>body{font:15px Arial;background:#f4f6fa;color:#172b43}.wrap{max-width:1150px;margin:30px auto;padding:0 15px}.card{background:#fff;padding:22px;border-radius:12px;margin:16px 0;overflow:auto}input{padding:10px;border:1px solid #ccd5df;border-radius:6px}button,a{background:#173d65;color:#fff;padding:9px 13px;border:0;border-radius:7px;text-decoration:none;cursor:pointer}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:11px;border-bottom:1px solid #eee}.active{color:#18794e}.inactive{color:#a45b18}</style></head><body><main class="wrap"><h1>Employee & User Management</h1><p><a href="{{ route('dashboard') }}">Dashboard</a> <a href="{{ route('employees.create') }}">＋ Create User</a></p>@if(session('success'))<p style="color:#18794e">{{ session('success') }}</p>@endif<div class="card"><form method="GET"><input name="search" value="{{ request('search') }}" placeholder="Search name, username or email"><button>Search</button></form><table><tr><th>Name</th><th>Username</th><th>Email</th><th>Role</th><th>Branch</th><th>Status</th><th>Actions</th></tr>@forelse($users as $u)<tr><td>{{ $u->name }}</td><td>{{ $u->username }}</td><td>{{ $u->email }}</td><td>{{ $u->roles->pluck('name')->join(', ') }}</td><td>{{ $u->branch?->name ?? 'System-wide' }}</td><td class="{{ $u->is_active?'active':'inactive' }}">{{ $u->is_active?'Active':'Inactive' }}</td><td><a href="{{ route('employees.edit',$u) }}">Edit</a> <form style="display:inline" method="POST" action="{{ route('employees.toggle',$u) }}">@csrf @method('PATCH')<button>{{ $u->is_active?'Deactivate':'Activate' }}</button></form></td></tr>@empty<tr><td colspan="7">No employees found.</td></tr>@endforelse</table>{{ $users->links() }}</div></main></body></html>